import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { vendorService } from '../../services/vendorService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage } from '../../utils/helpers';

const Home = () => {
  const [featuredVendors, setFeaturedVendors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { isAuthenticated, hasRole } = useAuth();

  useEffect(() => {
    loadFeaturedVendors();
  }, []);

  const loadFeaturedVendors = async () => {
    try {
      setLoading(true);
      const response = await vendorService.getAllPublicVendors();
      // Show only first 6 vendors as featured
      setFeaturedVendors(response.data.slice(0, 6));
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  const getDashboardLink = () => {
    if (hasRole('ROLE_ADMIN')) {
      return '/admin-dashboard';
    } else if (hasRole('ROLE_VENDOR')) {
      return '/vendor-dashboard';
    }
    return '/login';
  };

  const getDashboardText = () => {
    if (hasRole('ROLE_ADMIN')) {
      return 'Go to Admin Dashboard';
    } else if (hasRole('ROLE_VENDOR')) {
      return 'Go to Vendor Dashboard';
    }
    return 'Login to Your Account';
  };

  return (
    <div className="home-page">
      {/* Hero Section */}
      <section className="hero">
        <div className="container">
          <div className="hero-content">
            <h1>Welcome to FoodTruck Hub</h1>
            <p>Discover amazing food trucks in Chennai and Bangalore</p>
            
            <div className="hero-actions">
              <Link to="/vendors" className="btn btn-primary">
                Find Food Trucks
              </Link>
              
              {isAuthenticated() ? (
                <Link to={getDashboardLink()} className="btn btn-secondary">
                  {getDashboardText()}
                </Link>
              ) : (
                <Link to="/register" className="btn btn-secondary">
                  Register Your Truck
                </Link>
              )}
            </div>
          </div>
        </div>
      </section>

      {/* Stats Section */}
      <section className="stats">
        <div className="container">
          <div className="stats-grid">
            <div className="stat-item">
              <h3>{featuredVendors.length}+</h3>
              <p>Active Food Trucks</p>
            </div>
            <div className="stat-item">
              <h3>2</h3>
              <p>Cities Covered</p>
            </div>
            <div className="stat-item">
              <h3>1000+</h3>
              <p>Happy Customers</p>
            </div>
          </div>
        </div>
      </section>

      {/* Featured Vendors Section */}
      <section className="featured-vendors">
        <div className="container">
          <h2>Featured Food Trucks</h2>
          
          {loading ? (
            <LoadingSpinner message="Loading featured vendors..." />
          ) : error ? (
            <div className="error-message">
              <p>{error}</p>
              <button onClick={loadFeaturedVendors} className="btn btn-primary">
                Try Again
              </button>
            </div>
          ) : featuredVendors.length > 0 ? (
            <div className="vendors-grid">
              {featuredVendors.map((vendor) => (
                <div key={vendor.id} className="vendor-card">
                  <div className="vendor-info">
                    <h3>{vendor.name}</h3>
                    <p className="cuisine">{vendor.cuisineSpecialties}</p>
                    <p className="region">📍 {vendor.operatingRegion}</p>
                    {vendor.menuHighlights && (
                      <p className="menu-highlights">{vendor.menuHighlights}</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="no-vendors">
              <p>No food trucks available at the moment.</p>
              <Link to="/register" className="btn btn-primary">
                Be the first to register!
              </Link>
            </div>
          )}
          
          {featuredVendors.length > 0 && (
            <div className="view-all">
              <Link to="/vendors" className="btn btn-outline">
                View All Food Trucks
              </Link>
            </div>
          )}
        </div>
      </section>

      {/* How It Works Section */}
      <section className="how-it-works">
        <div className="container">
          <h2>How It Works</h2>
          <div className="steps-grid">
            <div className="step">
              <div className="step-number">1</div>
              <h3>Discover</h3>
              <p>Browse through our collection of verified food trucks in your city</p>
            </div>
            <div className="step">
              <div className="step-number">2</div>
              <h3>Choose</h3>
              <p>Select from a variety of cuisines and specialties</p>
            </div>
            <div className="step">
              <div className="step-number">3</div>
              <h3>Enjoy</h3>
              <p>Find your favorite food truck and enjoy delicious meals</p>
            </div>
          </div>
        </div>
      </section>

      {/* For Vendors Section */}
      {!isAuthenticated() && (
        <section className="vendor-cta">
          <div className="container">
            <div className="cta-content">
              <h2>Own a Food Truck?</h2>
              <p>Join our platform and reach more customers across Chennai and Bangalore</p>
              <Link to="/register" className="btn btn-primary">
                Register Your Food Truck
              </Link>
            </div>
          </div>
        </section>
      )}
    </div>
  );
};

export default Home;
